window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-67ff3989eb111ec8"]={"versions": [{"id": "FIG-67ff3989eb111ec8", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Aktivität aus der AUTOSAR-Methodik (Methodology) dar. Es handelt sich um ein methodisches Prozess- bzw. Datenflussdiagramm (AUTOSAR Activity Diagram), das den Schritt „Generate Compiler Configuration“ im Kontext der Konfiguration und Integration von Softwarekomponenten und Basissoftwaremodulen beschreibt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Aktivität ist die Task „Generate Compiler Configuration“.\\n\\nEingangsdaten («input»):\\n- „Atomic Software Component Implementation“ über die Rolle <code>+MemorySections</code> mit Kardinalität <code>0..*</code>\\n- „VFB Types“ über die Rolle <code>+SwAddrMethod</code> mit Kardinalität <code>1..*</code>\\n- „Basic Software Module Implementation Description“ über die Rolle <code>+MemorySections</code> mit Kardinalität <code>1..*</code>\\n- „BSW Module Preconfigured Configuration“ über die Rolle <code>+CompilerMemClassConfiguration</code> mit Kardinalität <code>1..*</code>\\n- BSW-/RTE-Konfigurationsbeschreibungen am unteren linken Rand:\\n  - Element mit Rolle <code>+ModuleDescription</code> und Kardinalität <code>0..1</code>\\n  - Element mit Rolle <code>+RteImplementationRef</code> und Kardinalität <code>0..1</code>\\n\\nAusgangsdaten («output»):\\n- „Standard Header Files“ über die Rolle <code>+Compiler_Cfg</code>\\n\\nAkteure / Rollen («performs»):\\n- „Basic Software Module Developer“ (Kardinalität <code>0..1</code>)\\n- „Software Component Developer“ (Kardinalität <code>0..1</code>)\\n- „ECU Integrator“ (Kardinalität <code>1</code>)</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität „Generate Compiler Configuration“ wird primär durch den ECU Integrator ausgeführt (Multiplizität 1), kann alternativ bzw. vorbereitend jedoch auch durch den Basic Software Module Developer oder den Software Component Developer durchgeführt werden (je 0..1).\\n\\nZur Durchführung aggregiert die Aktivität Spezifikationen zu Speichersektionen (<code>+MemorySections</code>) aus Software-Component- und BSW-Implementierungsbeschreibungen, Speicherabbildungsmethoden (<code>+SwAddrMethod</code>) aus den VFB-Typen sowie vorkonfigurierte Compiler-Speicherklassen (<code>+CompilerMemClassConfiguration</code>) und optionale Modul- bzw. RTE-Implementierungsreferenzen. Daraus wird als Artefakt die Compiler-Konfiguration (<code>+Compiler_Cfg</code>) in Form von Standard-Header-Dateien erzeugt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Erzeugung der Header-Datei <code>Compiler_Cfg.h</code> (bzw. entsprechender Standard Header Files) ist ein verbindlicher Teilschritt zur Sicherstellung der hersteller- und compilerspezifischen Speicherklassen- und Pointer-Makros. Entwickler müssen sicherstellen, dass sämtliche referenzierten <code>SwAddrMethod</code>-Definitionen und <code>MemorySection</code>-Einträge sowohl für BSW-Module als auch für SWCs mit den Compiler-Abstraktionsmakros konsistent abgebildet werden. Der ECU-Integrator trägt die Gesamtverantwortung für die finale Generierung der ECU-weiten Compiler-Konfigurationsheader.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-e477129a40053699", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine Aktivität aus der AUTOSAR-Methodik (Methodology) dar. Es handelt sich um ein methodisches Prozess- bzw. Datenflussdiagramm (AUTOSAR Activity Diagram), das den Schritt „Generate Compiler Configuration“ im Kontext der Konfiguration und Integration von Softwarekomponenten und Basissoftwaremodulen beschreibt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Aktivität ist die Task „Generate Compiler Configuration“.\\n\\nEingangsdaten («input»):\\n- „Atomic Software Component Implementation“ über die Rolle <code>+MemorySections</code> mit Kardinalität <code>0..*</code>\\n- „VFB Types“ über die Rolle <code>+SwAddrMethod</code> mit Kardinalität <code>1..*</code>\\n- „Basic Software Module Implementation Description“ über die Rolle <code>+MemorySections</code> mit Kardinalität <code>1..*</code>\\n- „BSW Module Preconfigured Configuration“ über die Rolle <code>+CompilerMemClassConfiguration</code> mit Kardinalität <code>1..*</code>\\n- BSW-/RTE-Konfigurationsbeschreibungen am unteren linken Rand:\\n  - Element mit Rolle <code>+ModuleDescription</code> und Kardinalität <code>0..1</code>\\n  - Element mit Rolle <code>+RteImplementationRef</code> und Kardinalität <code>0..1</code>\\n\\nAusgangsdaten («output»):\\n- „Standard Header Files“ über die Rolle <code>+Compiler_Cfg</code>\\n\\nAkteure / Rollen («performs»):\\n- „Basic Software Module Developer“ (Kardinalität <code>0..1</code>)\\n- „Software Component Developer“ (Kardinalität <code>0..1</code>)\\n- „ECU Integrator“ (Kardinalität <code>1</code>)</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität „Generate Compiler Configuration“ wird primär durch den ECU Integrator ausgeführt (Multiplizität 1), kann alternativ bzw. vorbereitend jedoch auch durch den Basic Software Module Developer oder den Software Component Developer durchgeführt werden (je 0..1).\\n\\nZur Durchführung aggregiert die Aktivität Spezifikationen zu Speichersektionen (<code>+MemorySections</code>) aus Software-Component- und BSW-Implementierungsbeschreibungen, Speicherabbildungsmethoden (<code>+SwAddrMethod</code>) aus den VFB-Typen sowie vorkonfigurierte Compiler-Speicherklassen (<code>+CompilerMemClassConfiguration</code>) und optionale Modul- bzw. RTE-Implementierungsreferenzen. Daraus wird als Artefakt die Compiler-Konfiguration (<code>+Compiler_Cfg</code>) in Form von Standard-Header-Dateien erzeugt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Erzeugung der Header-Datei <code>Compiler_Cfg.h</code> (bzw. entsprechender Standard Header Files) ist ein verbindlicher Teilschritt zur Sicherstellung der hersteller- und compilerspezifischen Speicherklassen- und Pointer-Makros. Entwickler müssen sicherstellen, dass sämtliche referenzierten <code>SwAddrMethod</code>-Definitionen und <code>MemorySection</code>-Einträge sowohl für BSW-Module als auch für SWCs mit den Compiler-Abstraktionsmakros konsistent abgebildet werden. Der ECU-Integrator trägt die Gesamtverantwortung für die finale Generierung der ECU-weiten Compiler-Konfigurationsheader.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-67ff3989eb111ec8", "to": "FIG-e477129a40053699", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
